/**
 * Her athletic bikini bottom, designed on her skin (src/sarahlab/athleticBottomStencil.ts and
 * public/models/paint/sarah-v2-athletic-bottom-field.png, generated by scripts/designAthleticBottom.mjs from Joshua's
 * reference and his drawing of its cut, 2026-11-12): its two lines decode to the body it was designed on and to
 * nothing else, its fill lies inside its edge, it covers her where his drawing covers and leaves her bare where it
 * does -- a triangle over her mons, a thin band to each hip, a V across her seat -- and its field in space round her
 * hips says the same as its values per vertex.
 */
import { beforeAll, describe, expect, it } from 'vitest';
import { NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { MeshoptDecoder } from 'meshoptimizer';
import sharp from 'sharp';
import { ATHLETIC_BOTTOM, athleticBottomField } from '../src/sarahlab/athleticBottomStencil';
import { fieldCells } from '../src/sarahlab/fabricMaterial';
import { COVERAGE_TEMPLATES, coverage, designedField, pieceKind, strapHeld } from '../src/sarahlab/paintTemplates';
import type { BodyMap } from '../src/sarahlab/bodyRegions';

let pos: Float32Array, raw: Float32Array, cells: Uint8Array;
beforeAll(async () => {
  await MeshoptDecoder.ready;
  const io = new NodeIO().registerExtensions(ALL_EXTENSIONS).registerDependencies({ 'meshopt.decoder': MeshoptDecoder });
  const doc = await io.read('assets-archive/models/sarah-v2-body.glb');
  // her rest frame (metres): the first joint's world matrix times its inverse bind
  const skin = doc.getRoot().listSkins()[0], J = skin.listJoints()[0].getWorldMatrix(), B = Array.from(skin.getInverseBindMatrices()!.getArray()!.slice(0, 16));
  const T = new Array(16).fill(0);
  for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++) for (let k = 0; k < 4; k++) T[c * 4 + r] += J[k * 4 + r] * B[c * 4 + k];
  const prim = doc.getRoot().listMeshes()[0].listPrimitives()[0], A = prim.getAttribute('POSITION')!, n = A.getCount(), v: number[] = [];
  pos = new Float32Array(n * 3); raw = new Float32Array(n * 3);
  for (let i = 0; i < n; i++) {
    A.getElement(i, v); for (let r = 0; r < 3; r++) { raw[i * 3 + r] = v[r]; pos[i * 3 + r] = T[r] * v[0] + T[4 + r] * v[1] + T[8 + r] * v[2] + T[12 + r]; }
  }
  // its field, read out of its picture as the room reads it
  const f = ATHLETIC_BOTTOM.field, { data, info } = await sharp(`public/${f.path}`).toColourspace('srgb').ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  cells = fieldCells(data, info.width, info.height, f.dims, f.cols)!;
}, 60000);

/**
 * The field at a place given as 0..1 of its block, blended between its cells as the room's shader blends it (0..1:
 * above one half is inside the outline); 0 outside the block, as the shader gives.
 */
function fieldAt(u: number, v: number, w: number): number {
  const [nx, ny, nz] = ATHLETIC_BOTTOM.field.dims;
  if (!(u > 0 && u < 1 && v > 0 && v < 1 && w > 0 && w < 1)) return 0;
  const gx = u * nx - 0.5, gy = v * ny - 0.5, gz = w * nz - 0.5, x0 = Math.floor(gx), y0 = Math.floor(gy), z0 = Math.floor(gz), fx = gx - x0, fy = gy - y0, fz = gz - z0;
  const at = (x: number, y: number, z: number) => cells[(Math.min(nz - 1, Math.max(0, z)) * ny + Math.min(ny - 1, Math.max(0, y))) * nx + Math.min(nx - 1, Math.max(0, x))] / 255;
  let sum = 0;
  for (let dz = 0; dz < 2; dz++) for (let dy = 0; dy < 2; dy++) for (let dx = 0; dx < 2; dx++) sum += (dx ? fx : 1 - fx) * (dy ? fy : 1 - fy) * (dz ? fz : 1 - fz) * at(x0 + dx, y0 + dy, z0 + dz);
  return sum;
}
/** The field at one of her vertices, looked up as the room looks it up: by its rest place in her mesh's own units. */
function fieldAtVertex(i: number): number {
  const d = designedField({ outline: 'athleticBottom', outlineLine: 'edge' }, ATHLETIC_BOTTOM.vertices)!.field;
  return fieldAt(raw[i * 3] * d.scale[0] + d.offset[0], raw[i * 3 + 1] * d.scale[1] + d.offset[1], raw[i * 3 + 2] * d.scale[2] + d.offset[2]);
}

/** The vertex of her rest skin nearest a point (metres, +y up, +z her front, +x her left). */
function nearest(p: readonly [number, number, number]): number {
  let best = -1, bd = Infinity;
  for (let i = 0; i < pos.length / 3; i++) {
    const d = (pos[i * 3] - p[0]) ** 2 + (pos[i * 3 + 1] - p[1]) ** 2 + (pos[i * 3 + 2] - p[2]) ** 2;
    if (d < bd) { bd = d; best = i; }
  }
  return best;
}
/** The field at a place in her rest frame (metres, +y up, +z her front, +x her left), as the room looks it up. */
function fieldAtPlace(p: readonly [number, number, number]): number {
  const d = designedField({ outline: 'athleticBottom', outlineLine: 'edge' }, ATHLETIC_BOTTOM.vertices)!.field, m = ATHLETIC_BOTTOM.field.toMetres;
  const unit = (k: number) => (p[k] - m.offset[k]) / m.scale;
  return fieldAt(unit(0) * d.scale[0] + d.offset[0], unit(1) * d.scale[1] + d.offset[1], unit(2) * d.scale[2] + d.offset[2]);
}
// points on her skin (MEASURED on her rest body, 2026-11-12), and whether his drawing's bottom covers them there
const LANDMARKS: readonly { name: string; at: [number, number, number]; covered: boolean }[] = [
  { name: 'her mons, under her bump', at: [0.0033, 0.838, 0.026], covered: true },
  { name: 'the wing across her left cheek', at: [0.08, 0.95, -0.205], covered: true },
  { name: 'the wing across her right cheek', at: [-0.0734, 0.95, -0.205], covered: true },
  { name: 'her navel', at: [0.0033, 0.99, 0.21], covered: false },
  { name: 'the underside of her bump', at: [0.0033, 0.88, 0.12], covered: false },
  { name: 'the front of her thigh', at: [0.1, 0.83, 0.037], covered: false },
  { name: 'the lower outer part of her cheek', at: [0.12, 0.835, -0.17], covered: false },
  { name: 'the side of her hip, under the band', at: [0.19, 0.935, -0.09], covered: false },
  { name: 'the top of her cleft, over the notch', at: [0.0033, 0.985, -0.16], covered: false },
  { name: 'the small of her back', at: [0.0033, 1.05, -0.12], covered: false },
];
// places on her skin along the band over her left hip (MEASURED from the outline's own curves, 2026-11-12): the band's
// middle, and a centimetre over its upper edge and under its lower one. The band is narrower than her triangles are
// wide there, so no vertex of hers says it: the field is asked at the place itself.
const BAND: readonly { name: string; mid: [number, number, number]; over: [number, number, number]; under: [number, number, number] }[] = [
  { name: 'along the fold under her bump', mid: [0.1125, 0.8942, 0.0315], over: [0.1027, 0.9056, 0.0327], under: [0.1237, 0.881, 0.0303] },
  { name: 'at the front of her hip', mid: [0.1582, 0.9498, -0.0071], over: [0.1505, 0.9615, 0.0034], under: [0.1657, 0.938, -0.0176] },
  { name: 'at her side', mid: [0.1725, 0.9771, -0.0756], over: [0.1651, 0.9927, -0.0731], under: [0.177, 0.9606, -0.0782] },
  { name: 'behind her hip', mid: [0.1579, 0.9816, -0.1365], over: [0.1503, 0.9967, -0.1332], under: [0.1628, 0.965, -0.1384] },
];

describe('her athletic bikini bottom, designed on her skin (Joshua, 2026-11-12)', () => {
  it('decodes both its lines to the body it was designed on, and to nothing else', () => {
    expect(athleticBottomField('edge', 5)).toBeNull();
    const edge = athleticBottomField('edge', ATHLETIC_BOTTOM.vertices)!, fill = athleticBottomField('fill', ATHLETIC_BOTTOM.vertices)!;
    expect(edge).toHaveLength(115710);
    expect(fill).toHaveLength(115710);
    expect(athleticBottomField('edge')).toBe(edge);
  });

  it('keeps its values within reach, its fill inside its edge, and a bikini bottom of her skin inside it', () => {
    const edge = athleticBottomField('edge')!, fill = athleticBottomField('fill')!, far = Math.fround(ATHLETIC_BOTTOM.far);
    let outOfReach = 0, fillOutside = 0, inEdge = 0, inFill = 0;
    for (let v = 0; v < edge.length; v++) {
      if (!(Math.abs(edge[v]) <= far && Math.abs(fill[v]) <= far)) outOfReach++;
      if (fill[v] > 0 && !(edge[v] > 0)) fillOutside++;
      if (edge[v] > 0) inEdge++;
      if (fill[v] > 0) inFill++;
    }
    expect(outOfReach).toBe(0);
    expect(fillOutside).toBe(0);
    expect(inEdge).toBeGreaterThan(4000);
    expect(inEdge).toBeLessThan(7000);
    // the edging is a thin band: the fill holds most of it
    expect(inFill).toBeGreaterThan(inEdge * 0.7);
  });

  it('covers her where his drawing covers, and leaves her bare where it does', () => {
    const edge = athleticBottomField('edge')!;
    for (const l of LANDMARKS) expect({ name: l.name, covered: edge[nearest(l.at)] > 0 }).toEqual({ name: l.name, covered: l.covered });
  });

  it('draws the same garment in its field in space, looked up by her rest places in her mesh\'s own units', () => {
    expect(cells).toHaveLength(ATHLETIC_BOTTOM.field.dims[0] * ATHLETIC_BOTTOM.field.dims[1] * ATHLETIC_BOTTOM.field.dims[2]);
    for (const l of LANDMARKS) expect({ name: l.name, covered: fieldAtVertex(nearest(l.at)) > 0.5 }).toEqual({ name: l.name, covered: l.covered });
    // the band over each hip: its middle covered, her skin a centimetre either side of it bare -- and red at its
    // middle (farther inside the outline than the edging is wide), as laid: its designed width within a millimetre
    const mirrored = (p: readonly [number, number, number]) => [2 * 0.0033 - p[0], p[1], p[2]] as const, red = 0.5 + ATHLETIC_BOTTOM.band / (2 * ATHLETIC_BOTTOM.field.range);
    for (const b of BAND) for (const side of [(p: readonly [number, number, number]) => p, mirrored]) {
      expect({ name: b.name, mid: fieldAtPlace(side(b.mid)) > red, over: fieldAtPlace(side(b.over)) > 0.5, under: fieldAtPlace(side(b.under)) > 0.5 }).toEqual({ name: b.name, mid: true, over: false, under: false });
    }
    expect(ATHLETIC_BOTTOM.sideBand.width).toBe(0.015);
    for (const laid of ATHLETIC_BOTTOM.sideBand.laid) expect(Math.abs(laid - ATHLETIC_BOTTOM.sideBand.width)).toBeLessThan(0.001);
    // and vertex by vertex: on the same side of the outline as its own value says, wherever that value is clear of the
    // line (a value within 2 mm of it may sit either side: per vertex the line is blended across her triangles)
    const edge = athleticBottomField('edge')!, R = ATHLETIC_BOTTOM.field.range;
    let clear = 0, wrong = 0, near = 0, off = 0;
    for (let i = 0; i < edge.length; i++) {
      if (Math.abs(edge[i]) < 0.002 || Math.abs(edge[i]) >= ATHLETIC_BOTTOM.far - 1e-6) continue;
      const f = fieldAtVertex(i);
      clear++;
      if ((f > 0.5) !== (edge[i] > 0)) wrong++;
      // within the field's range, the two are the same distance, to a millimetre and a half
      if (Math.abs(edge[i]) < R * 0.8) { near++; if (Math.abs((f - 0.5) * 2 * R - edge[i]) > 0.0015) off++; }
    }
    expect(clear).toBeGreaterThan(6000);
    expect(wrong / clear).toBeLessThan(0.002);
    expect(off / near).toBeLessThan(0.03);
    // her skin outside its block is not the garment: the shader gives 0 there
    expect(fieldAtVertex(nearest([0.0033, 1.45, 0.05]))).toBe(0);
  });

  it('reads its field out of its picture, and only out of its own', () => {
    const f = ATHLETIC_BOTTOM.field, [nx, ny] = f.dims;
    // a 2 x 1 x 3 field, two slices to a row: the third slice starts the second row
    const px = (grey: number[]) => Uint8Array.from(grey.flatMap((g) => [g, g, g, 255]));
    expect(Array.from(fieldCells(px([1, 2, 3, 4, 5, 6, 0, 0]), 4, 2, [2, 1, 3], 2)!)).toEqual([1, 2, 3, 4, 5, 6]);
    expect(fieldCells(px([1, 2, 3, 4, 5, 6, 0, 0]), 4, 2, [2, 1, 3], 3)).toBeNull();
    expect(fieldCells(new Uint8Array(16), nx * f.cols, ny, f.dims, f.cols)).toBeNull();
  });

  it('hangs its strap on her pelvis: a V about her middle that cuts nothing off the design at rest, and holds it to 3 cm when her skin spreads', () => {
    const d = designedField({ outline: 'athleticBottom', outlineLine: 'edge' }, ATHLETIC_BOTTOM.vertices)!.field, strap = d.strap!;
    expect(strap.bone).toBe('Bone_000');
    // one unit of her mesh on the field's scale, and a millimetre of it
    const mm = 0.001 * d.unitsPerMetre * strap.perUnit;
    expect(mm).toBeCloseTo(0.001 / (2 * ATHLETIC_BOTTOM.field.range), 9);
    // at rest (her bones have carried nothing) every vertex the design paints stays painted, and its value is cut by
    // less than half a millimetre anywhere the design is more than a millimetre inside its outline
    let painted = 0, lost = 0, cut = 0;
    for (let i = 0; i < raw.length / 3; i++) {
      const at = [raw[i * 3], raw[i * 3 + 1], raw[i * 3 + 2]] as const, v = fieldAtVertex(i);
      if (v <= 0.5 + mm) continue;
      const held = strapHeld(v, at, at, strap);
      painted++;
      if (held <= 0.5) lost++;
      cut = Math.max(cut, Math.min(v, 0.5 + 5 * mm) - Math.min(held, 0.5 + 5 * mm));
    }
    expect(painted).toBeGreaterThan(4000);
    expect(lost).toBe(0);
    expect(cut).toBeLessThan(0.5 * mm);
    // under her crotch: skin of the gusset carried 5 mm aside by her legs is still the strap; carried 2 cm aside it is bare
    const u = d.unitsPerMetre, floor = nearest([0.0033 + 0.004, 0.82, -0.05]), at = [raw[floor * 3], raw[floor * 3 + 1], raw[floor * 3 + 2]] as const, v = fieldAtVertex(floor);
    expect(v).toBeGreaterThan(0.5 + 2 * mm);
    expect(strapHeld(v, at, [at[0] + 0.005 * u, at[1], at[2]], strap)).toBeGreaterThan(0.5);
    expect(strapHeld(v, at, [at[0] + 0.02 * u, at[1], at[2]], strap)).toBeLessThan(0.5);
    // the strap is 3 cm wide there: its edge is 15 mm from her middle
    const edge = (x: number) => strapHeld(1, at, [strap.mid + x * u, at[1], at[2]], strap);
    expect(edge(0.0149)).toBeGreaterThan(0.5);
    expect(edge(0.0151)).toBeLessThan(0.5);
    // and her hip is no part of it: the band there rides her skin wherever her bones carry it
    const hip = nearest([0.1725, 0.9771, -0.0756]), hipAt = [raw[hip * 3], raw[hip * 3 + 1], raw[hip * 3 + 2]] as const;
    for (const hv of [fieldAtVertex(hip), 0.9]) expect(strapHeld(hv, hipAt, [hipAt[0] + 0.1 * u, hipAt[1] - 0.1 * u, hipAt[2]], strap)).toBe(hv);
  });

  it('is two paint layers, a fill over an edging, read off the field at its two lines', () => {
    const fill = COVERAGE_TEMPLATES.find((t) => t.id === 'athleticBottom')!, edging = COVERAGE_TEMPLATES.find((t) => t.id === 'athleticBottomEdge')!;
    expect(pieceKind(fill.id)).toBe('bottom');
    expect(pieceKind(edging.id)).toBe('bottom');
    const e = designedField(edging.params, ATHLETIC_BOTTOM.vertices)!, f = designedField(fill.params, ATHLETIC_BOTTOM.vertices)!;
    expect(e.field.path).toBe(ATHLETIC_BOTTOM.field.path);
    expect(f.field).toBe(e.field);
    expect(e.level).toBe(0.5);
    // the fill's line is the edging's width inside the outline, on the field's scale
    expect(f.level).toBeCloseTo(0.5 + ATHLETIC_BOTTOM.band / (2 * ATHLETIC_BOTTOM.field.range), 9);
    expect(designedField(fill.params, 5)).toBeNull();
    // the block's corners in her mesh's own units are its 0 and 1
    for (let k = 0; k < 3; k++) {
      expect(e.field.lo[k] * e.field.scale[k] + e.field.offset[k]).toBeCloseTo(0, 9);
      expect(e.field.hi[k] * e.field.scale[k] + e.field.offset[k]).toBeCloseTo(1, 9);
    }
    // its paint per vertex follows its own line's values
    const map = { region: new Uint8Array(ATHLETIC_BOTTOM.vertices) } as unknown as BodyMap;
    const c = coverage(map, fill.params), values = athleticBottomField('fill')!;
    let disagree = 0;
    for (let v = 0; v < c.length; v++) if ((c[v] > 0.5) !== (values[v] > 0)) disagree++;
    expect(disagree).toBe(0);
  });
});
